#[cfg(test)]
mod reviewed_families {
    use crate::{
        domain::{
            models::{entity_search::EntitySearchRequest, funder::FunderId},
            repositories::{entity_details::EntityDetailsRepo, funder_repository::FunderRepo},
        },
        outbound::postgres::ExposedDatabase,
    };
    use sqlx::PgPool;

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures("../../../../db/fixtures/add_members.sql")
    )]
    async fn reviewed_families_combine_all_names_and_preserve_distinct_evidence(pool: PgPool) -> sqlx::Result<()> {
        sqlx::query!("INSERT INTO exposed.declarations (source_declaration_id, member_id, category_id, category_name, fetched_at) SELECT 9999, id, 1, 'Employment and earnings', now() FROM exposed.members ORDER BY id LIMIT 1").execute(&pool).await?;
        let db = ExposedDatabase::from(pool.clone());
        let families = [
            ("bbc", "BBC", vec!["BBC", "BBC Contributor Payments", "BBC Home Services", "BBC  Studios", "BBC Studios Ltd", "BBC Wales Cymru"]),
            ("gb_news", "GB News", vec!["GB News", "GB News Limited", "GB News Ltd"]),
            ("premier_league", "Premier League", vec!["Premier League", "FA Premier League Ltd", "The FA Premier League Ltd", "The Premier League", "Premier League International Holdings Ltd"]),
        ];
        let mut next_id = 1;
        for (family_key, term, names) in families {
            let mut ids = Vec::new();
            for name in &names {
                let id = uuid::Uuid::from_u128(next_id);
                next_id += 1;
                ids.push(id);
                sqlx::query!("INSERT INTO exposed.funders (id, funder_name) VALUES ($1, $2)", id, name).execute(&pool).await?;
                sqlx::query!("INSERT INTO exposed.funding_entries (source_declaration_id, funder_id, amount, currency) VALUES (9999, $1, 10, 'GBP')", id).execute(&pool).await?;
            }
            let external = uuid::Uuid::from_u128(next_id);
            next_id += 1;
            sqlx::query!("INSERT INTO exposed.funders (id, funder_name) VALUES ($1, 'Alias-connected source')", external).execute(&pool).await?;
            sqlx::query!("INSERT INTO exposed.funder_aliases (funder_id, funder_alias) VALUES ($1, $2)", external, term).execute(&pool).await?;
            sqlx::query!("INSERT INTO exposed.funding_entries (source_declaration_id, funder_id, amount, currency) VALUES (9999, $1, 5, 'GBP')", external).execute(&pool).await?;
            ids.push(external);
            let request = EntitySearchRequest::new_with_strictness(term.into(), 10, 0.8).unwrap();
            let results = db.get_funders_by_text_search_score(&request).await.unwrap().matches;
            assert_eq!(results.len(), 1, "{term}");
            assert_eq!(results[0].0.funder().id().value(), ids[0]);
            for id in &ids {
                let details = db.funder_funding(FunderId::new(*id)).await.unwrap().unwrap();
                assert_eq!(details.profile.funder.id().value(), *id);
                assert_eq!(details.profile.member_ids.iter().map(|id| id.value()).collect::<Vec<_>>(), ids);
                assert_eq!(details.allocations.len(), 1);
                assert_eq!(details.allocations[0].entry_count, i64::try_from(ids.len()).unwrap());
                assert_eq!(details.allocations[0].known_total, Some(bigdecimal::BigDecimal::from(names.len() * 10 + 5)));
                assert_eq!(details.profile.family_links.len(), names.len() * (names.len() - 1) / 2);
                assert!(details.profile.family_links.iter().all(|link| link.family_key == family_key && link.left_funder_id.value() != external && link.right_funder_id.value() != external));
                assert!(details.profile.family_links.iter().any(|link| link.left_name == names[0] && link.right_name == names[1]));
                assert!(details.profile.alias_links.iter().any(|link| link.right_funder_id.value() == external && link.right_alias == term));
                assert!(details.profile.alias_links.iter().all(|link| link.normalized_alias == term.to_lowercase()));
                for name in &names {
                    assert!(details.profile.aliases.contains(&(*name).into()));
                }
            }
        }
        sqlx::query!("INSERT INTO exposed.funders (funder_name) VALUES ('Labour Party'), ('Mauritius Labour Party')").execute(&pool).await?;
        let request = EntitySearchRequest::new_with_strictness("Labour Party".into(), 10, 0.8).unwrap();
        let results = db.get_funders_by_text_search_score(&request).await.unwrap().matches;
        assert_eq!(results.len(), 2);
        for (matched, _) in results {
            let profile = db.funder_funding(matched.funder().id()).await.unwrap().unwrap().profile;
            assert_eq!(profile.member_ids.len(), 1);
            assert!(profile.family_links.is_empty());
        }
        Ok(())
    }
}
